# The Fusion implementation of the decad, sketch and r3 operations that translated gallery models call.
#
# A gear add-in generated by port/cmd/gearport holds Python translated from a decad-gallery model. That code calls
# the functions named <package>_<operation> below (decad_extrude, sketch_new_radius, r3_new_vec) and the methods of
# the classes below, one for each entry of the API table in port/go2py/api.go. Everything Fusion needs that the
# gallery does not say lives here, once, for every gear: where a sketch's origin goes, how a dimension binds to a
# user parameter, how an axial edge is found on a body. docs/fusion/playbook.md and docs/fusion/spurgear.md hold the
# Fusion findings behind each rule, quoted here by anchor.
#
# The translated code is the gallery's: it creates sketches, features and bodies in the gallery's order, and passes
# the role name of each one it creates. This module never decides geometry.

import functools
import hashlib
import math
import os
import tempfile
import time
from contextlib import contextmanager
from typing import cast
import adsk.core
import adsk.fusion
from ...lib import fusion360utils as futil
from . import solids

DECAD_ALONG = 1
DECAD_AGAINST = -1

# Two coordinates closer than this, in cm, are one value to Fusion's sketch solver.
SAME_COORDINATE = 1e-6

# The error Fusion raises for a dimension or constraint the sketch already fixes. [SPUR-F-ALIGN-DUPLICATE]
OVER_CONSTRAINED = 'VCS_SKETCH_OVER_CONSTRAINTS'

def source_hash(path):
    """The first 12 hex digits of the SHA-1 of a file, or 'unreadable'."""
    try:
        with open(path, 'rb') as source:
            return hashlib.sha1(source.read()).hexdigest()[:12]
    except OSError:
        return 'unreadable'


# The hash of this file when Fusion imported it. Fusion keeps imported modules across an add-in Stop and Run, so a
# deploy of this file can leave the old code running; the command compares this with the file on disk.
# [PB-STALE-MODULE]
RUNTIME_BUILD = source_hash(__file__)


def runtime_is_stale():
    return source_hash(__file__) != RUNTIME_BUILD


# The active runtime. A translated function reaches the design through the objects it is handed, except
# sketch_new_world(), which the gallery calls with no argument.
_active = None


# Fusion's Text Commands window does not repaint while the add-in blocks the main thread, so a step that never
# returns leaves no trace there. The progress file is written and flushed line by line, so it shows the step a hung
# build stopped in.
PROGRESS_FILE = os.path.join(tempfile.gettempdir(), 'geargen-progress.log')


def progress_reset():
    """Empty the progress file, so it holds the steps of one build. The command calls it before each build."""
    try:
        with open(PROGRESS_FILE, 'w'):
            pass
    except OSError:
        pass


def progress(message):
    try:
        with open(PROGRESS_FILE, 'a') as out:
            out.write(f'{time.strftime("%H:%M:%S")} {message}\n')
            out.flush()
            os.fsync(out.fileno())
    except OSError:
        pass


@contextmanager
def timed(what):
    """Log how long a step takes, so a slow build shows which operation is slow."""
    progress(f'start {what}')
    start = time.perf_counter()
    try:
        yield
    finally:
        message = f'{what}: {time.perf_counter() - start:.2f}s'
        progress(message)
        futil.log(message)


def logged(function):
    """Time a decad operation under its role name."""
    @functools.wraps(function)
    def wrapper(*args, **kwargs):
        with timed(kwargs.get('name') or function.__name__):
            return function(*args, **kwargs)
    return wrapper


class SketchOnly(Exception):
    """Raised by the first extrude when the dialog asks for sketches only, which ends the build."""


class FusionRefused(RuntimeError):
    """Fusion answered null, or fewer results than the build needs, where the API reports a failure that way.
    [PB-EMPTY-RESULT]"""


class Untranslated(RuntimeError):
    """The translated build asked for something this runtime has no Fusion form for, such as an axis, a plane or an
    extent it cannot represent. Raised instead of building something else."""


class ConsumedBody(RuntimeError):
    """A body that an earlier union consumed was used again. Fusion's join deletes its tools, so the eager sequence
    of features would fail at the same step."""


class Vec:
    def __init__(self, x, y, z):
        self.x, self.y, self.z = x, y, z

    def add(self, other):
        return Vec(self.x + other.x, self.y + other.y, self.z + other.z)

    def sub(self, other):
        return Vec(self.x - other.x, self.y - other.y, self.z - other.z)

    def scale(self, k):
        return Vec(self.x * k, self.y * k, self.z * k)

    def len(self):
        return math.sqrt(self.x * self.x + self.y * self.y + self.z * self.z)

    def dot(self, other):
        return self.x * other.x + self.y * other.y + self.z * other.z

    def cross(self, other):
        return Vec(self.y * other.z - self.z * other.y, self.z * other.x - self.x * other.z,
                   self.x * other.y - self.y * other.x)

    def unit(self):
        n = self.len()
        return Vec(self.x / n, self.y / n, self.z / n)

    # The gallery's r3.Vec names its fields in capitals.
    X = property(lambda self: self.x)
    Y = property(lambda self: self.y)
    Z = property(lambda self: self.z)


def r3_new_vec(x, y, z):
    return Vec(x, y, z)


def r3_vec(X=0.0, Y=0.0, Z=0.0):
    """The gallery's r3.Vec{} literal: a vector with the fields it names, the others zero."""
    return Vec(X, Y, Z)


def vec_of(point):
    return Vec(point.x, point.y, point.z)


class Frame:
    """An origin and three axes in world cm. n is the gear axis and the normal of the sketch plane."""

    def __init__(self, origin, u, v, n):
        self._origin, self._u, self._v, self._n = origin, u, v, n

    def origin(self):
        return self._origin

    def u(self):
        return self._u

    def v(self):
        return self._v

    def n(self):
        return self._n

    def is_valid(self):
        return True


def r3_new_frame(origin, u, v):
    return Frame(origin, u, v, u.cross(v).unit())


# Fusion units whose parameter value is not a length: an angle is in radians and a unitless value is a number
# whatever the runtime's length unit. [PB-UNITS]
_NOT_LENGTH_UNITS = {'', 'deg', 'rad'}


class Value:
    """A user parameter. base() is its value in the unit of the translated code; expression names it for a
    dimension or a feature. [PB-UNITS]"""

    def __init__(self, name, parameter, scale=1.0):
        self.expression = name
        self._parameter = parameter
        self._scale = scale

    def base(self):
        """Fusion holds a length in centimetres, an angle in radians and a unitless value as it is. Only a length
        changes with the runtime's unit."""
        value = self._parameter.value
        if self._scale == 1.0 or self._parameter.unit in _NOT_LENGTH_UNITS:
            return value
        return value / self._scale


class Distance:
    def __init__(self, D, Dir):
        self.D, self.Dir = D, Dir


def decad_distance(D, Dir):
    return Distance(D, Dir)


class DistanceSide:
    def __init__(self, D):
        self.D = D


def decad_distance_side(D):
    return DistanceSide(D)


class TwoSided:
    """An extent that reaches One from the sketch along its normal and Two against it."""

    def __init__(self, One, Two):
        self.One, self.Two = One, Two


def decad_two_sided(One, Two):
    return TwoSided(One, Two)


def units_millimeters(x):
    """x millimetres in the length unit of the translated code: the number itself in a millimetre runtime (scale
    0.1), a tenth of it in a centimetre runtime (scale 1.0). [PB-UNITS]"""
    if _active is None:
        raise RuntimeError('units_millimeters needs an active runtime to know the unit of the translated code')
    return x * 0.1 / _active.scale


class CircularPattern:
    def __init__(self, Center, Axis, Count):
        self.Center, self.Axis, self.Count = Center, Axis, Count


def decad_circular_pattern(Center, Axis, Count):
    return CircularPattern(Center, Axis, Count)


def value_input(value, scale=1.0):
    """A ValueInput for a Value (its user parameter, so the feature stays parametric) or a number, which is in
    the unit of the translated code and becomes centimetres by scale. [PB-UNITS]"""
    if isinstance(value, Value):
        return adsk.core.ValueInput.createByString(value.expression)
    return adsk.core.ValueInput.createByReal(value * scale)


# ---------------------------------------------------------------------------------------------
# Numbers, units and the parameter table of a model that computes its dimensions from expressions


UNITS_MILLIMETER = 'mm'
UNITS_RADIAN = 'rad'
UNITS_ONE = ''


def units_radians(x):
    return x


def math_round(x):
    """Go's math.Round: the nearest integer, halfway cases away from zero, computed exactly. Adding 0.5 first is not
    exact: 0.49999999999999994 + 0.5 rounds to 1.0 in floating point, where Go gives 0."""
    if math.isnan(x) or math.isinf(x):
        return x
    whole = float(math.trunc(x))
    # x - whole is exact: both share x's exponent range and whole drops only x's fraction bits.
    if abs(x - whole) >= 0.5:
        whole += math.copysign(1.0, x)
    return math.copysign(whole, x)


def math_ilogb(x):
    """Go's math.Ilogb: the binary exponent of x as an integer."""
    return math.frexp(x)[1] - 1


class FieldRef:
    """A pointer to a number field of a translated struct: Go's &d.field. value reads and writes the field."""

    def __init__(self, owner, field):
        self._owner, self._field = owner, field

    @property
    def value(self):
        return getattr(self._owner, self._field)

    @value.setter
    def value(self, number):
        setattr(self._owner, self._field, number)


def field_ref(owner, field):
    return FieldRef(owner, field)


class Quantity:
    """A number the parameter table holds, in the unit of the translated code."""

    def __init__(self, number):
        self._number = number

    def base(self):
        return self._number


# The functions a gallery parameter expression may call.
_EXPRESSION_FUNCTIONS = {
    'hypot': math.hypot, 'atan2': math.atan2, 'sin': math.sin, 'cos': math.cos, 'tan': math.tan, 'sqrt': math.sqrt,
    'min': min, 'max': max, 'pow': pow, 'abs': abs, 'atan': math.atan, 'asin': math.asin, 'acos': math.acos,
}


class ParamTable:
    """A model's parameter table, computed in Python. A model whose sketches bind no dimension to a parameter keeps
    its dimensions here, and no Fusion user parameter is made for them: the gallery's bevel gear derives its
    cone angles, radii and face width from expressions it only reads back. [PB-PARAM-TABLE]"""

    def __init__(self):
        self.values = {}

    def set_value(self, name, value):
        self.values[name] = float(value)

    def set_number(self, name, value):
        self.values[name] = float(value)

    def set_expr(self, name, expr, unit):
        names = dict(_EXPRESSION_FUNCTIONS)
        names.update(self.values)
        try:
            self.values[name] = float(eval(compile(expr, name, 'eval'), {'__builtins__': {}}, names))
        except NameError as error:
            raise RuntimeError(f'parameter {name}: {error}') from error

    def get_value(self, name):
        if name not in self.values:
            raise RuntimeError(f'parameter {name} is not defined')
        return Quantity(self.values[name])


def param_new():
    return ParamTable()


def shaft_snap(frame, section):
    """The gallery snaps the points of a section about a rotated shaft to a grid, so that decad's revolve about that axis
    sees exact floats. Fusion's kernel is exact, and the snap does harm there: the grid depends on the section's reach,
    so the same surface drawn in two sections lands on two slightly different cones, and Fusion keeps the faces apart where
    it merges the faces of an unsnapped gear. The section is returned as it is. [PB-NO-GRID-SNAP]"""
    return list(section)


class Container:
    """The gallery's container: a group of bodies that nest. Fusion makes a component for it once the build is done,
    and moves its bodies in, because a feature on a body inside a component would run in that component's
    context. Sketches and planes stay in the component the build runs in, so they keep following the anchor.
    [PB-CONTAINER-BODIES]"""

    def __init__(self, runtime, name, parent=None):
        self._runtime, self._name, self._parent = runtime, name, parent
        self._children = []
        self.bodies = []
        # The occurrence a body moves to, once the component exists.
        self.context = None

    def name(self):
        return self._name

    def children(self):
        return list(self._children)

    def new_child(self, name):
        child = Container(self._runtime, name, self)
        self._children.append(child)
        return child

    def add_sketch(self, sketch):
        sketch.container = self

    def add_plane(self, plane):
        plane.container = self

    def holds_bodies(self):
        return bool(self.bodies) or any(child.holds_bodies() for child in self._children)

    def realize(self, component, context):
        """Make the components of the children that hold bodies, and move the bodies in."""
        for child in self._children:
            if not child.holds_bodies():
                continue
            occurrence: adsk.fusion.Occurrence = component.occurrences.addNewComponent(adsk.core.Matrix3D.create())
            occurrence.component.name = child._name
            child.context = occurrence if context is None else occurrence.createForAssemblyContext(context)
            for body in child.bodies:
                moved = body.body.moveToComponent(child.context)
                if moved is None:
                    raise FusionRefused(f'{child._name}: Fusion did not move body {body.body.name} into the component')
                body.body = moved
            child.realize(occurrence.component, child.context)


class Runtime:
    """The design a translated gallery model builds in. It is the gallery's Document and World."""

    def __init__(self, component, plane, anchor, parameters, sketch_only=False, scale=1.0):
        # scale is the centimetres of one unit of length in the translated code. The spur-family gears run in
        # centimetres (1.0). A gallery model with absolute lengths in millimetres runs in millimetres (0.1), and
        # the runtime converts at every place a length enters or leaves Fusion. [PB-UNITS]
        self.scale = scale
        # component: the adsk.fusion.Component to build in.
        # plane: the ConstructionPlane the lower cap lies on.
        # anchor: a SketchPoint at the gear centre, projected into a fully constrained sketch.
        # parameters: a function from a gallery table name to (Fusion parameter name, adsk Parameter).
        self.component = component
        self.plane = plane
        self.anchor = anchor
        self._parameters = parameters
        self.sketch_only = sketch_only
        self.sketches = []
        self.helpers = []
        self._names = {}
        # The parameter table of a model that computes its dimensions in Python, and the gallery's containers.
        self._table = ParamTable()
        self._root = Container(self, component.name)
        self._axes = {}
        # True when the gallery's axes are not the sketch plane's own: the build lies across the sketch plane.
        self.mapped = False
        # The gallery builds a gear about the local origin and +Z. frame is that local frame, and
        # placement is where it lies in the design: the anchor, the sketch's axes and their normal.
        self.frame: Frame = Frame(Vec(0, 0, 0), Vec(1, 0, 0), Vec(0, 1, 0), Vec(0, 0, 1))
        self.placement: Frame = self.frame

    def activate(self):
        global _active
        _active = self
        return self

    def build_frame(self, sketch, u=None, v=None):
        """Place the gear: its origin is the anchor and its axes are the sketch's. [SPUR-F-LOCAL-ORIGIN]

        Returns the local frame the translated code builds in. Positions that come out of the design
        (vertices of edges) are in that frame, and positions that go in (the pattern axis, a plane's
        frame, an edge's end point) are mapped to the design, as the gallery's Place does at the end.
        """
        if u is None:
            u = vec_of(sketch.xDirection)
            v = vec_of(sketch.yDirection)
        else:
            # The gallery's U and V are given in the design, in the sketch's plane: a gear whose shaft is the gallery's U
            # stands on a plane it lies across. The sketch's own axes then map to them. [PB-FRAME-PLANE]
            self.mapped = True
        # A sketch point has a world position; a construction point's position is already in the design's space.
        position = self.anchor.worldGeometry if hasattr(self.anchor, 'worldGeometry') else self.anchor.geometry
        self.placement = Frame(vec_of(position), u, v, u.cross(v).unit())
        return self.frame

    def to_world(self, point):
        p = self.placement
        local = point.scale(self.scale)
        return p.origin().add(p.u().scale(local.x)).add(p.v().scale(local.y)).add(p.n().scale(local.z))

    def to_world_dir(self, direction):
        p = self.placement
        return p.u().scale(direction.x).add(p.v().scale(direction.y)).add(p.n().scale(direction.z))

    def to_local(self, point):
        p = self.placement
        d = point.sub(p.origin()).scale(1.0 / self.scale)
        return Vec(d.dot(p.u()), d.dot(p.v()), d.dot(p.n()))

    # decad.Document
    def param(self, name):
        if name in self._table.values:
            return self._table.get_value(name)
        parameterName, parameter = self._parameters(name)
        return Value(parameterName, parameter, self.scale)

    def root(self):
        return self._root

    def bodies(self):
        """Every body of the component, the same wrapper for the same body. Bodies are matched with ==: one entity can
        return different entityToken strings over time, so tokens are never compared."""
        registry = self.__dict__.setdefault('_bodyRegistry', [])
        found = []
        for fbody in self.component.bRepBodies:
            wrapper = next((known for known in registry if known.body == fbody), None)
            if wrapper is None:
                wrapper = Body(self, fbody)
                registry.append(wrapper)
            found.append(wrapper)
        return found

    def move_body(self, body, container):
        if body.container is not None:
            body.container.bodies.remove(body)
        container.bodies.append(body)
        body.container = container

    def container_of(self, body):
        return body.container if body.container is not None else self._root

    def finish_containers(self):
        """Make a component for each container that holds a body and move the bodies in. [PB-CONTAINER-BODIES]"""
        self._root.realize(self.component, None)

    # sketch.World, and decad.Document: the parameter table
    def params(self):
        return self._table

    def xy(self):
        return Plane(self, self.plane, frame=self.frame if self.mapped else None)

    def unique(self, name):
        """A role name that repeats gets an index: Tooth Profile, Tooth Profile 2."""
        count = self._names.get(name, 0) + 1
        self._names[name] = count
        return name if count == 1 else f'{name} {count}'

    def derive(self, p):
        """The gear dimensions, read from the user parameters the gallery table defines."""
        class Dimensions:
            pass
        d = Dimensions()
        d.pitch, d.base = self.param('pitch_radius').base(), self.param('base_radius').base()
        d.root, d.tip = self.param('root_radius').base(), self.param('tip_radius').base()
        d.fillet = self.param('fillet_radius').base()
        return d

    def create_sketch(self, plane, name):
        name = self.unique(name)
        fsketch: adsk.fusion.Sketch = self.component.sketches.add(plane.entity)
        solids.name_feature(fsketch, name)
        fsketch.isVisible = True
        sketch = Sketch(self, fsketch, plane=plane)
        self.sketches.append(fsketch)
        return sketch

    def create_plane_from_frame(self, frame, name):
        """A construction plane for a gallery frame, which a sketch on it maps its coordinates through. Two kinds are
        translated: a frame across the base plane with its origin in the base plane, and a frame that is the build's
        own frame moved along its normal. Any other frame raises Untranslated, because a sketch on its plane would be
        drawn somewhere else. [PB-FRAME-PLANE]"""
        across = frame.n().dot(self.frame.n())
        height = frame.origin().sub(self.frame.origin()).dot(self.frame.n())
        if abs(across) < 1e-9:
            if abs(height) > 1e-9:
                raise Untranslated(f'{name}: a plane across the base plane is translated only through a point of the base '
                                   f'plane; its origin is {height:g} off it')
            return self._plane_across(frame, name)
        if abs(abs(across) - 1.0) > 1e-9:
            raise Untranslated(f'{name}: a plane that is neither parallel nor perpendicular to the base plane is not '
                               'translated')
        shift = frame.origin().sub(self.frame.origin()).sub(self.frame.n().scale(height))
        if across < 0 or shift.len() > 1e-9 or frame.u().sub(self.frame.u()).len() > 1e-9 \
                or frame.v().sub(self.frame.v()).len() > 1e-9:
            raise Untranslated(f'{name}: a plane parallel to the base plane is translated only as the build frame moved '
                               'along its normal; this frame is reversed, turned or moved within the plane')
        offset = height * self.scale
        name = self.unique(name)
        planes: adsk.fusion.ConstructionPlanes = self.component.constructionPlanes
        planeInput: adsk.fusion.ConstructionPlaneInput = planes.createInput()
        planeInput.setByOffset(self.plane, adsk.core.ValueInput.createByReal(offset))
        entity = planes.add(planeInput)
        solids.name_feature(entity, name)
        entity.isLightBulbOn = True
        self.helpers.append(entity)
        return Plane(self, entity, frame=self.frame if self.mapped else None)

    def _plane_across(self, frame, name):
        """A plane perpendicular to the base plane through the frame's origin: a Fusion-only sketch holds a
        construction line from the origin along the frame's normal, and the plane is normal to that line at its start.
        The line follows the anchor, so the plane does. [PB-FRAME-PLANE]"""
        name = self.unique(name)
        helper = self.create_sketch(self.xy(), name + ' Axis')
        direction = Vec(frame.n().x, frame.n().y, 0).unit()
        origin = frame.origin()
        start = helper.dimension_point(origin.x, origin.y)
        end = helper.dimension_point(origin.x + direction.x, origin.y + direction.y)
        line = helper.create_line(start, end)
        line.set_construction(True)
        helper.solve()
        planes: adsk.fusion.ConstructionPlanes = self.component.constructionPlanes
        planeInput: adsk.fusion.ConstructionPlaneInput = planes.createInput()
        planeInput.setByDistanceOnPath(line.fusion, adsk.core.ValueInput.createByReal(0))
        entity = planes.add(planeInput)
        solids.name_feature(entity, name)
        entity.isLightBulbOn = True
        self.helpers.append(entity)
        return Plane(self, entity, frame=frame, anchor=start.point)

    def axis_line(self, center, direction, name):
        """A construction line from center along direction, in a Fusion-only sketch on the base plane, for a revolve or
        a pattern about an axis. The sketch being revolved cannot hold it: adding a curve to a sketch invalidates the
        profiles already read from it. One line serves every use of the same axis. [PB-FRAME-PLANE]

        The line lies in the base plane, so an axis that leaves the plane, or does not start in it, has no line here and
        is refused rather than replaced by its projection."""
        length = direction.len()
        if length < 1e-12:
            raise Untranslated(f'{name}: the axis has no direction')
        if abs(direction.z) > 1e-9 * length or abs(center.z) > 1e-9:
            raise Untranslated(f'{name}: an axis through ({center.x:g}, {center.y:g}, {center.z:g}) along '
                               f'({direction.x:g}, {direction.y:g}, {direction.z:g}) does not lie in the base plane, and '
                               'only a cylindrical face or a line in the base plane makes a construction axis here')
        unit = Vec(direction.x, direction.y, 0).unit()
        key = tuple(round(v, 9) for v in (center.x, center.y, unit.x, unit.y))
        if key in self._axes:
            return self._axes[key]
        helper = self.create_sketch(self.xy(), name)
        if abs(center.x) < 1e-12 and abs(center.y) < 1e-12:
            start = helper.origin()
        else:
            start = helper.dimension_point(center.x, center.y)
        end = helper.dimension_point(center.x + unit.x, center.y + unit.y)
        line = helper.create_line(start, end)
        line.set_construction(True)
        helper.solve()
        self._axes[key] = line.fusion
        return line.fusion

    def hide_helpers(self):
        for entity in self.helpers:
            entity.isLightBulbOn = False
        for fsketch in self.sketches:
            fsketch.isVisible = False


def sketch_new_world():
    return _active


def derive(p):
    return _active.derive(p)


class Plane:
    def __init__(self, runtime, entity, frame=None, anchor=None):
        self.runtime, self.entity = runtime, entity
        # The gallery frame a plane across the base plane was made from, and the sketch point at its origin. A sketch
        # on such a plane maps the frame's axes to Fusion's, and anchors on that point. [PB-FRAME-PLANE]
        self.frame, self.anchor = frame, anchor
        self.container = None


class Circle:
    """A circle the gallery drew: the Fusion circle and the point the gallery placed its centre by."""

    def __init__(self, circle, center):
        self.circle = circle
        self.Center = center


class Spline:
    """A fitted spline the gallery asked for. Fusion creates it when the sketch is drawn."""

    def __init__(self, points):
        self.points = points
        self.fusion = None


class Constraint:
    """A dimension that a sketch will create: a radius or a diameter of a circle."""

    def __init__(self, kind, circle, value):
        self.kind, self.value = kind, value
        self.circle = circle.circle if isinstance(circle, Circle) else circle
        self.dimension = None


def sketch_new_radius(circle, value):
    return Constraint('radius', circle, value)


def sketch_new_diameter(circle, value):
    return Constraint('diameter', circle, value)


class PendingPoint:
    """A point the gallery places by coordinates. Fusion creates it with the first curve that uses it."""

    def __init__(self, x, y, arcEnd):
        self.x = x
        self.y = y
        # An arc end is placed by one coordinate; its radius comes from the arc or circle it ends.
        self.arcEnd = arcEnd
        # The SketchPoint, once a curve has created it.
        self.point = None


class Profile:
    Valid = True

    def __init__(self, fprofile):
        self.fprofile = fprofile
        self.Outer = []
        self.Holes = []
        for loop in fprofile.profileLoops:
            if loop.isOuter:
                self.Outer = [curve for curve in loop.profileCurves]
            else:
                self.Holes.append([curve for curve in loop.profileCurves])
        # The sketch entities on the outer boundary, so a line the build drew compares equal to its entity.
        self.Entities = [EntityRef(curve.sketchEntity) for curve in self.Outer]


class EntityRef:
    """A sketch entity of a profile. It equals a Line the build drew when the line's Fusion entity is the same entity,
    compared with ==: one entity can return different entityToken strings over time, so tokens are never compared."""

    def __init__(self, entity):
        self.entity = entity

    def __eq__(self, other):
        if isinstance(other, EntityRef):
            return self.entity == other.entity
        fusion = getattr(other, 'fusion', None)
        return fusion is not None and fusion == self.entity

    # Equality follows Fusion's ==, which no hash can follow.
    __hash__ = None


class Line:
    """A line the gallery drew: the points it joins, and the Fusion line once the sketch is drawn."""

    def __init__(self, start, end):
        self.start, self.end = start, end
        self.construction = False
        self.fusion = None

    def set_construction(self, flag):
        self.construction = flag


def _coordinates(point):
    """The gallery coordinates of a pending point; a Fusion point the build passes in (the sketch origin) is at 0, 0."""
    return (point.x, point.y) if isinstance(point, PendingPoint) else (0.0, 0.0)


class Chain:
    """Sketch curves that join end to end, open or closed."""

    def __init__(self, curves):
        self.curves = curves


class Sketch:
    """A Fusion sketch the translated gallery code draws in.

    The gallery calls dimension_point, dimension_arc_end, create_line, create_arc, create_fit_spline and
    create_circle in its own order. This class records them and draws them in solve(), in the order Fusion
    needs: splines first, so every line and arc ends on a spline's own fit points, then lines, arcs, the
    dimensions from the local origin, and last the coincident constraint that moves the local origin onto the
    anchor. [SPUR-F-GALLERY-SKETCH] [SPUR-F-ARC-CENTRE] [SPUR-F-ALIGN-DUPLICATE] [SPUR-F-LOCAL-ORIGIN]
    """

    def __init__(self, runtime, fsketch, origin=None, rootCircle=None, rootRadius=None, plane=None):
        self.runtime = runtime
        self._scale = runtime.scale if runtime is not None else 1.0
        self.sketch: adsk.fusion.Sketch = fsketch
        # A sketch on a plane across the base plane has axes of Fusion's choosing. The gallery's coordinates map to
        # them by the dot products of the frame's axes and the sketch's, and the point the plane was made at anchors
        # the local origin. The sketch's normal runs against the frame's when the map is a reflection. [PB-FRAME-PLANE]
        self._map = (1.0, 0.0, 0.0, 1.0)
        self.flipped = False
        self._anchorPoint = runtime.anchor if runtime is not None else None
        self.container = None
        if plane is not None and plane.frame is not None:
            x, y = vec_of(fsketch.xDirection), vec_of(fsketch.yDirection)
            u, v = runtime.to_world_dir(plane.frame.u()).unit(), runtime.to_world_dir(plane.frame.v()).unit()
            self._map = (u.dot(x), v.dot(x), u.dot(y), v.dot(y))
            self.flipped = self._map[0] * self._map[3] - self._map[1] * self._map[2] < 0
            if plane.anchor is not None:
                self._anchorPoint = plane.anchor
        self._lineHandles = []
        # The local origin is a point the anchor constraint can move, which the sketch's own origin is not.
        self._origin = origin if origin is not None else fsketch.sketchPoints.add(adsk.core.Point3D.create(0, 0, 0))
        # A caller that draws the root circle itself passes it, and the root arc then lies on that circle.
        self._rootCircle = rootCircle
        self._rootRadius = rootRadius
        self._points = []
        self._lines = []
        self._arcs = []
        self._splines = []
        self._patterns = []
        self._constraints = []
        self._bindings = []
        self._dimensioned = []

    def _xy(self, x, y):
        a, b, c, d = self._map
        return a * x + b * y, c * x + d * y

    def _p3(self, x, y):
        fx, fy = self._xy(x, y)
        return adsk.core.Point3D.create(fx * self._scale, fy * self._scale, 0)

    # sketch.Sketch
    def origin(self):
        return self._origin

    def dimension_point(self, x, y):
        point = PendingPoint(x, y, False)
        self._points.append(point)
        return point

    def dimension_arc_end(self, x, y):
        point = PendingPoint(x, y, True)
        self._points.append(point)
        return point

    def create_line(self, start, end):
        line = Line(start, end)
        self._lines.append(line)
        self._lineHandles.append(line)
        return line

    def find_axis_line(self, axis):
        """The construction line this sketch drew along axis from the same start, or None. The line may be longer
        than the axis the gallery names."""
        start, end = (axis.Start.U, axis.Start.V), (axis.End.U, axis.End.V)
        near = lambda a, b: abs(a[0] - b[0]) < 1e-9 and abs(a[1] - b[1]) < 1e-9
        wanted = (end[0] - start[0], end[1] - start[1])
        for line in self._lineHandles:
            if not line.construction or line.fusion is None or not near(_coordinates(line.start), start):
                continue
            own = (_coordinates(line.end)[0] - start[0], _coordinates(line.end)[1] - start[1])
            scale = math.hypot(*own) * math.hypot(*wanted)
            if scale > 0 and abs(own[0] * wanted[1] - own[1] * wanted[0]) < 1e-9 * scale \
                    and own[0] * wanted[0] + own[1] * wanted[1] > 0:
                return line.fusion
        return None

    def create_arc(self, center, start, end):
        self._arcs.append((center, start, end))

    def create_fit_spline(self, *points):
        spline = Spline(points)
        self._splines.append(spline)
        return spline

    def create_point(self, x, y):
        """A point the gallery places without dimensioning it: the pattern places it."""
        return PendingPoint(x, y, False)

    def create_pattern_circular_ring(self, splines, center, n, start, end):
        """A circular pattern of splines about center, n copies in all, closing into a ring. [PB-SPLINE-RING]"""
        self._patterns.append((splines, center, n, start, end))
        return splines[0]

    def create_circle(self, center, radius):
        circles: adsk.fusion.SketchCircles = self.sketch.sketchCurves.sketchCircles
        if isinstance(center, PendingPoint):
            # A circle whose centre the gallery dimensions from the origin: Fusion makes the centre point with
            # the circle, and the dimension step then places it.
            circle = circles.addByCenterRadius(self._p3(center.x, center.y), radius * self._scale)
            center.point = circle.centerSketchPoint
            return Circle(circle, center)
        return Circle(circles.addByCenterRadius(center, radius * self._scale), center)

    def add_constraint(self, constraint):
        self._constraints.append(constraint)

    def bind(self, constraint, table, name):
        self._bindings.append((constraint, name))

    def solve(self):
        with timed(f'{self.sketch.name} solve'):
            self.finish(self._anchorTimed)

    def _anchorTimed(self):
        with timed(f'{self.sketch.name} anchor'):
            self._anchor()

    def profiles(self):
        return [Profile(profile) for profile in self.sketch.profiles]

    def chains(self):
        """The drawn lines that join end to end, one chain. A line drawn as construction is not part of one."""
        curves = [line.fusion for line in self._lineHandles if not line.construction and line.fusion is not None]
        return [Chain(curves)] if curves else []

    # The drawing
    def finish(self, anchor=None):
        """Draw everything recorded. A caller passes the step that moves the local origin onto the anchor, which runs
        last, or before the patterns when the sketch has any: [PB-SPLINE-RING]"""
        with timed(f'{self.sketch.name} draw'):
            self._drawSplines()
            self._drawLines()
            self._drawArcs()
        with timed(f'{self.sketch.name} dimension {len(self._points)} points'):
            for point in self._points:
                self._dimensionPoint(point)
            self._points = []
            for constraint in self._constraints:
                self._dimensionCircle(constraint)
            self._constraints = []
        if anchor is not None and self._patterns:
            anchor()
            anchor = None
        for pattern in self._patterns:
            with timed(f'{self.sketch.name} pattern'):
                self._pattern(*pattern)
        self._patterns = []
        for constraint, name in self._bindings:
            self._bind(constraint, name)
        self._bindings = []
        if anchor is not None:
            anchor()

    def _anchor(self):
        """Move the local origin onto the anchor, last, once every dimension is in place. [SPUR-F-LOCAL-ORIGIN]"""
        projected = adsk.fusion.SketchPoint.cast(self.sketch.project(self._anchorPoint).item(0))
        if projected is None:
            raise RuntimeError(f'{self.sketch.name}: anchor projection produced no SketchPoint')
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        constraints.addCoincident(self._origin, projected)

    def _drawSplines(self):
        splines: adsk.fusion.SketchFittedSplines = self.sketch.sketchCurves.sketchFittedSplines
        for spline in self._splines:
            collection = adsk.core.ObjectCollection.create()
            for point in spline.points:
                collection.add(self._p3(point.x, point.y))
            spline.fusion = splines.add(collection)
            fits: adsk.fusion.SketchPointList = spline.fusion.fitPoints
            for i, point in enumerate(spline.points):
                point.point = fits.item(i)
        self._splines = []

    def _pattern(self, splines, center, n, start, end):
        """Copy the seed splines n - 1 times about center, then tie the seed's free end to the first copy's start.
        Fusion's copies carry their own points and the closed outline needs only that one coincident: every
        neighbouring pair would add redundant constraints. [PB-SPLINE-RING]"""
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        centre = center.point if isinstance(center, PendingPoint) else center
        patternInput = constraints.createCircularPatternInput([spline.fusion for spline in splines], centre)
        patternInput.quantity = adsk.core.ValueInput.createByReal(n)
        patternInput.totalAngle = adsk.core.ValueInput.createByString('360 deg')
        pattern = constraints.addCircularPattern(patternInput)
        if pattern is None:
            raise RuntimeError(f'{self.sketch.name}: the circular pattern was not created')
        # The first copy starts where the seed's start turned one step about the centre.
        origin, first = centre.geometry, start.point.geometry
        step = 2 * math.pi / n
        dx, dy = first.x - origin.x, first.y - origin.y
        target = (origin.x + dx * math.cos(step) - dy * math.sin(step), origin.y + dx * math.sin(step) + dy * math.cos(step))
        nearest, gap = None, None
        for entity in pattern.createdEntities:
            fitted = adsk.fusion.SketchFittedSpline.cast(entity)
            if fitted is None:
                continue
            point = fitted.fitPoints.item(0)
            distance = math.hypot(point.geometry.x - target[0], point.geometry.y - target[1])
            if gap is None or distance < gap:
                nearest, gap = point, distance
        if nearest is None or gap > SAME_COORDINATE * 100:
            raise RuntimeError(f'{self.sketch.name}: no copy of the pattern starts where the seed ends')
        constraints.addCoincident(end.point, nearest)

    def _end(self, point):
        if not isinstance(point, PendingPoint):
            return point
        if point.point is not None:
            return point.point
        return self._p3(point.x, point.y)

    def _drawLines(self):
        lines: adsk.fusion.SketchLines = self.sketch.sketchCurves.sketchLines
        for handle in self._lines:
            start, end = handle.start, handle.end
            line: adsk.fusion.SketchLine = lines.addByTwoPoints(self._end(start), self._end(end))
            handle.fusion = line
            if handle.construction:
                line.isConstruction = True
            if isinstance(start, PendingPoint) and start.point is None:
                start.point = line.startSketchPoint
            if isinstance(end, PendingPoint) and end.point is None:
                end.point = line.endSketchPoint
        self._lines = []

    def _onRootCircle(self, point):
        assert self._rootRadius is not None
        return abs(math.hypot(point.x, point.y) - self._rootRadius) < SAME_COORDINATE

    def _drawArcs(self):
        arcs: adsk.fusion.SketchArcs = self.sketch.sketchCurves.sketchArcs
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        for center, start, end in self._arcs:
            if self._rootCircle is not None and self._onRootCircle(start) and self._onRootCircle(end):
                # The root arc is part of the root circle the caller already drew, which the parameters size.
                # Its ends sit on that circle instead of getting a second arc. [SPUR-F-ROOT-ARC]
                for point in (start, end):
                    point.arcEnd = True
                    constraints.addCoincident(point.point, self._rootCircle)
                continue
            # An arc runs counter-clockwise from its start; a reflected map reverses that. [PB-FRAME-PLANE]
            first, last = (end, start) if self.flipped else (start, end)
            arc: adsk.fusion.SketchArc = arcs.addByCenterStartEnd(center, first.point, last.point)
            # Fusion makes its own centre point for the arc; tie it to the local origin. [SPUR-F-ARC-CENTRE]
            constraints.addCoincident(arc.centerSketchPoint, center)
        self._arcs = []

    def _dimensionPoint(self, point):
        horizontal = adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation
        vertical = adsk.fusion.DimensionOrientations.VerticalDimensionOrientation
        if not point.arcEnd:
            self._dimension(point, horizontal)
            self._dimension(point, vertical)
        else:
            fx, fy = self._xy(point.x, point.y)
            if abs(fx) >= abs(fy):
                self._dimension(point, vertical)
            else:
                self._dimension(point, horizontal)
        self._dimensioned.append(point)

    def _dimension(self, point, orientation):
        dims: adsk.fusion.SketchDimensions = self.sketch.sketchDimensions
        textPoint = self._p3(point.x, point.y)
        try:
            dims.addDistanceDimension(self._origin, point.point, orientation, textPoint)
            return
        except RuntimeError as error:
            # Only the refusal the probes recorded is replaced; any other refusal is the build's error.
            partner = self._sameCoordinate(point, orientation) if OVER_CONSTRAINED in str(error) else None
            if partner is None:
                raise
            refusal = error
        # Fusion refuses a second dimension with the value and direction of an earlier one from the
        # same origin, as at tooth angle 0 where both flanks start at one x. Aligning the two points
        # fixes the same coordinate. [SPUR-F-ALIGN-DUPLICATE]
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        try:
            if orientation == adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation:
                constraints.addVerticalPoints(point.point, partner.point)
            else:
                constraints.addHorizontalPoints(point.point, partner.point)
        except RuntimeError as alignment:
            raise RuntimeError(f'{self.sketch.name}: Fusion refused a distance dimension ({refusal}) and the alignment '
                               f'that replaces it ({alignment})') from refusal

    def _sameCoordinate(self, point, orientation):
        horizontal = orientation == adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation
        px, py = self._xy(point.x, point.y)
        for other in self._dimensioned:
            ox, oy = self._xy(other.x, other.y)
            if abs((ox - px) if horizontal else (oy - py)) < SAME_COORDINATE:
                return other
        return None

    def _dimensionCircle(self, constraint):
        dims: adsk.fusion.SketchDimensions = self.sketch.sketchDimensions
        radius = constraint.circle.radius
        textPoint = adsk.core.Point3D.create(radius, radius, 0)
        if constraint.kind == 'radius':
            constraint.dimension = dims.addRadialDimension(constraint.circle, textPoint)
        else:
            constraint.dimension = dims.addDiameterDimension(constraint.circle, textPoint)

    def _bind(self, constraint, name):
        """Drive the dimension from the user parameter the gallery bound it to."""
        parameterName, _ = self.runtime._parameters(name)
        constraint.dimension.parameter.expression = parameterName


def unconstrained_entities(fsketch, limit=24):
    """Describe the curves and fit points a sketch leaves free, in mm, so a failed check says what to constrain."""
    found = []
    curves = fsketch.sketchCurves
    for i in range(curves.count):
        curve = curves.item(i)
        if curve.isFullyConstrained:
            continue
        kind = curve.objectType.split('::')[-1]
        start = curve.startSketchPoint.geometry if hasattr(curve, 'startSketchPoint') else None
        where = '' if start is None else f' from ({start.x * 10:.3f}, {start.y * 10:.3f})'
        loose = []
        fitted = adsk.fusion.SketchFittedSpline.cast(curve)
        if fitted is not None:
            for j in range(fitted.fitPoints.count):
                point = fitted.fitPoints.item(j)
                if not point.isFullyConstrained:
                    loose.append(f'{j}:({point.geometry.x * 10:.3f}, {point.geometry.y * 10:.3f})')
        found.append(f'{kind}{where}' + (f' free fit points {", ".join(loose)}' if loose else ''))
    points = fsketch.sketchPoints
    for i in range(points.count):
        point = points.item(i)
        if not point.isFullyConstrained:
            found.append(f'point ({point.geometry.x * 10:.3f}, {point.geometry.y * 10:.3f})')
    more = len(found) - limit
    return found[:limit] + ([f'and {more} more'] if more > 0 else [])


def sketchcheck_verify_fully_constrained(sketch):
    with timed(f'{sketch.sketch.name} constraint check'):
        constrained = sketch.sketch.isFullyConstrained
    if not constrained:
        free = unconstrained_entities(sketch.sketch)
        raise RuntimeError(f'{sketch.sketch.name}: sketch is not fully constrained; free: ' + '; '.join(free))


# ---------------------------------------------------------------------------------------------
# Bodies, features and edge selection


class Box:
    def __init__(self, low, high):
        self._low, self._high = low, high

    # The gallery's box names its corners in capitals.
    Min = property(lambda self: self._low)
    Max = property(lambda self: self._high)


class Body:
    def __init__(self, runtime, body):
        self.runtime = runtime
        self.body: adsk.fusion.BRepBody = body
        # The gallery container the body belongs to; None is the root. [PB-CONTAINER-BODIES]
        self.container = None

    def bounds(self):
        """The smallest box around the body in the build's local frame. The body's bounding box in the design is
        axis-aligned in the design, so its corners are mapped to the local frame, which can make the box larger than
        the body; a caller that only needs the body's reach along a direction gets a safe margin."""
        _settle(self)
        box = self.body.boundingBox
        corners = [Vec(x, y, z) for x in (box.minPoint.x, box.maxPoint.x) for y in (box.minPoint.y, box.maxPoint.y)
                   for z in (box.minPoint.z, box.maxPoint.z)]
        local = [self.runtime.to_local(corner) for corner in corners]
        return Box(Vec(min(c.x for c in local), min(c.y for c in local), min(c.z for c in local)),
                   Vec(max(c.x for c in local), max(c.y for c in local), max(c.z for c in local)))

    def is_solid(self):
        _settle(self)
        return self.body.isSolid

    def centroid(self):
        _settle(self)
        return Centroid(self.runtime, self.body.physicalProperties.centerOfMass)

    def faces(self):
        _settle(self)
        return [Face(self.runtime, f, self) for f in self.body.faces]

    def extreme_faces_by_centroid(self, axis):
        """The faces with the least and the greatest centroid along axis, a direction of the build frame."""
        ranked = []
        for face in self.faces():
            ranked.append((face.centroid().Value.dot(axis), face))
        if len(ranked) < 2:
            raise RuntimeError(f'body {self.body.name} has {len(ranked)} faces; need two to find the extremes')
        ranked.sort(key=lambda entry: entry[0])
        return ranked[0][1], ranked[-1][1]


class Position:
    def __init__(self, runtime, point):
        self.Value = runtime.to_local(vec_of(point))
        # Fusion reports a point as a number, with no certified error. [PB-READING-BOUND]
        self.Bound = Length(0.0)


class Centroid:
    def __init__(self, runtime, point):
        self.Value = runtime.to_local(vec_of(point))
        self.Bound = Length(0.0)


class Vertex:
    def __init__(self, runtime, point):
        self._runtime = runtime
        self._point = point

    def position(self):
        return Position(self._runtime, self._point)

    def _key(self):
        return (round(self._point.x, 6), round(self._point.y, 6), round(self._point.z, 6))

    def __hash__(self):
        return hash(self._key())

    def __eq__(self, other):
        return isinstance(other, Vertex) and self._key() == other._key()


class Edge:
    def __init__(self, runtime, edge):
        self.runtime = runtime
        self.edge: adsk.fusion.BRepEdge = edge
        self._ends = None
        self._axial = None

    def ends(self):
        if self._ends is None:
            self._ends = (self.edge.startVertex.geometry, self.edge.endVertex.geometry)
        return self._ends

    def is_axial(self):
        if self._axial is None:
            axis = self.runtime.placement.n()
            a, b = (vec_of(p) for p in self.ends())
            d = b.sub(a)
            length = d.len()
            self._axial = length > 0 and abs(abs(d.dot(axis)) - length) <= 1e-6 * max(length, 1.0)
        return self._axial

    def end(self):
        """The end of an axial edge on the upper cap, the other end from start()."""
        a, b = self.ends()
        s = self.start()
        return Vertex(self.runtime, b) if s._point is a else Vertex(self.runtime, a)

    def curve(self):
        if self.edge.geometry.curveType == adsk.core.Curve3DTypes.Line3DCurveType:
            return Line3()
        return Curve()

    def __hash__(self):
        return hash(self.edge.tempId)

    def __eq__(self, other):
        return isinstance(other, Edge) and self.edge.tempId == other.edge.tempId

    def axisDirection(self):
        a, b = (vec_of(p) for p in self.ends())
        return b.sub(a).unit()

    def start(self):
        """The end of an axial edge on the lower cap; an edge that is not axial keeps Fusion's start."""
        a, b = self.ends()
        axis = self.runtime.placement.n()
        if self.is_axial() and vec_of(b).dot(axis) < vec_of(a).dot(axis):
            return Vertex(self.runtime, b)
        return Vertex(self.runtime, a)


class Curve:
    """A curve of an edge that is not a straight line."""


class Line3(Curve):
    """A straight edge."""


def decad_is_line3(curve):
    return isinstance(curve, Line3)


class Length:
    def __init__(self, value):
        self._value = value

    def base(self):
        return self._value


class Surface:
    """A surface of a face that is not a cylinder."""


class Cylinder(Surface):
    def __init__(self, radius):
        self.Radius = Length(radius)


def decad_is_cylinder(surface):
    return isinstance(surface, Cylinder)


class Face:
    def __init__(self, runtime, face, owner=None):
        self.runtime = runtime
        self.face: adsk.fusion.BRepFace = face
        # The Body the face was read from, when it was read from one.
        self.owner = owner

    def surface(self):
        if self.face.geometry.surfaceType == adsk.core.SurfaceTypes.CylinderSurfaceType:
            return Cylinder(cast(adsk.core.Cylinder, self.face.geometry).radius / self.runtime.scale)
        return Surface()

    def edges(self):
        return [Edge(self.runtime, e) for e in self.face.edges]

    def centroid(self):
        return Centroid(self.runtime, self.face.centroid)


class Predicate:
    """A condition on the edges of a body. matches() receives the Edge and the body it came from."""

    def __init__(self, test):
        self.test = test

    def matches(self, edge, body):
        return self.test(edge, body)


def decad_parallel_to(axis):
    def test(edge, body):
        a, b = (vec_of(p) for p in edge.ends())
        if not isinstance(edge.curve(), Line3) or b.sub(a).len() == 0:
            return False
        world = edge.runtime.to_world_dir(axis).unit()
        return abs(abs(edge.axisDirection().dot(world)) - 1) < 1e-6
    return Predicate(test)


def decad_endpoint_at(point):
    def test(edge, body):
        world = edge.runtime.to_world(point)
        return any(vec_of(p).sub(world).len() <= SAME_COORDINATE for p in edge.ends())
    return Predicate(test)


def decad_circular():
    def test(edge, body):
        return edge.edge.geometry.curveType in (
            adsk.core.Curve3DTypes.Circle3DCurveType, adsk.core.Curve3DTypes.Arc3DCurveType)
    return Predicate(test)


def decad_longer_than(length):
    def test(edge, body):
        return edge.edge.length / edge.runtime.scale > length
    return Predicate(test)


def decad_concave():
    # The concave edges are asked of Fusion once per selection, not once per edge.
    memo = {}

    def test(edge, body):
        if 'tokens' not in memo:
            memo['tokens'] = {e.tempId for e in body.body.concaveEdges}
        return edge.edge.tempId in memo['tokens']
    return Predicate(test)


class FaceSelector:
    """Planar end caps of a body: the faces perpendicular to the gear axis at its lowest or highest position."""

    def __init__(self, high):
        self.high = high
        self.body = None


def decad_cap_start(body):
    selector = FaceSelector(False)
    selector.body = body
    return selector


def decad_cap_end(body):
    selector = FaceSelector(True)
    selector.body = body
    return selector


def cap_faces(runtime, body, high):
    axis = runtime.placement.n()
    planar = []
    for face in body.body.faces:
        if face.geometry.surfaceType != adsk.core.SurfaceTypes.PlaneSurfaceType:
            continue
        plane = cast(adsk.core.Plane, face.geometry)
        normal = vec_of(plane.normal)
        if abs(abs(normal.dot(axis)) - 1.0) > 1e-6:
            continue
        planar.append((vec_of(plane.origin).dot(axis), face))
    if not planar:
        return []
    extreme = max(h for h, _ in planar) if high else min(h for h, _ in planar)
    return [face for h, face in planar if abs(h - extreme) <= 1e-5]


def decad_outer_loop_of(selector):
    # The cap's outer loop is read once per selection, not once per edge.
    memo = {}

    def test(edge, body):
        if 'tokens' not in memo:
            tokens = set()
            for face in cap_faces(edge.runtime, selector.body, selector.high):
                for loop in face.loops:
                    if loop.isOuter:
                        tokens.update(e.tempId for e in loop.edges)
            memo['tokens'] = tokens
        return edge.edge.tempId in memo['tokens']
    return Predicate(test)


class Selector:
    def __init__(self, groups, count=None):
        self.groups = groups
        self.count = count

    def or_(self, *predicates):
        """Add a group of conditions, in place, as the gallery's EdgeQuery does."""
        self.groups.append(list(predicates))
        return self

    def exactly(self, count):
        self.count = count
        return self

    def select_edges(self, body):
        edges = []
        for fedge in body.body.edges:
            edge = Edge(body.runtime, fedge)
            if any(all(p.matches(edge, body) for p in group) for group in self.groups):
                edges.append(edge)
        return edges


def decad_edges(*predicates):
    return Selector([list(predicates)])


def _edge_collection(selector, body, what):
    edges = selector.select_edges(body)
    if selector.count is not None and len(edges) != selector.count:
        raise RuntimeError(f'{what}: selected {len(edges)} edges, want {selector.count}')
    collection = adsk.core.ObjectCollection.create()
    for edge in edges:
        collection.add(edge.edge)
    if collection.count == 0:
        raise RuntimeError(f'{what}: no edges selected')
    return collection


@logged
def decad_extrude(doc, sketch, profile, extent, name, body):
    if doc.sketch_only:
        raise SketchOnly()
    extrudes: adsk.fusion.ExtrudeFeatures = doc.component.features.extrudeFeatures
    operation = adsk.fusion.FeatureOperations.NewBodyFeatureOperation
    reversed_ = sketch.flipped
    if isinstance(profile, Chain):
        # An open chain extrudes to a sheet, a surface body.
        path = doc.component.createOpenProfile(profile.curves[0], True)
        extrudeInput: adsk.fusion.ExtrudeFeatureInput = extrudes.createInput(path, operation)
        extrudeInput.isSolid = False
    else:
        extrudeInput = extrudes.createInput(profile.fprofile, operation)
    if isinstance(extent, TwoSided):
        # Side one runs along the sketch's normal, which runs against the frame's when the plane's map is a
        # reflection. [PB-FRAME-PLANE]
        along, against = (extent.Two, extent.One) if reversed_ else (extent.One, extent.Two)
        extrudeInput.setTwoSidesExtent(
            adsk.fusion.DistanceExtentDefinition.create(value_input(along.D, doc.scale)),
            adsk.fusion.DistanceExtentDefinition.create(value_input(against.D, doc.scale)))
    else:
        distance = adsk.fusion.DistanceExtentDefinition.create(value_input(extent.D, doc.scale))
        # The sketch's normal runs against the frame's when the plane's map is a reflection. [PB-FRAME-PLANE]
        along = (extent.Dir == DECAD_ALONG) != reversed_
        direction = (adsk.fusion.ExtentDirections.PositiveExtentDirection if along
                     else adsk.fusion.ExtentDirections.NegativeExtentDirection)
        extrudeInput.setOneSideExtent(distance, direction)
    extrude: adsk.fusion.ExtrudeFeature = extrudes.add(extrudeInput)
    solids.name_feature(extrude, name)
    if extrude.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {extrude.bodies.count}')
    fbody: adsk.fusion.BRepBody = extrude.bodies.item(0)
    solids.name_feature(fbody, body)
    return _placed(Body(doc, fbody), sketch)


def _placed(body, source):
    """A body made from a sketch or from another body belongs to the container the gallery put that source in."""
    if source is not None and source.container is not None:
        body.runtime.move_body(body, source.container)
    return body


def _axis_through(runtime, pattern, name):
    """A construction axis along the pattern axis: the axis of a cylindrical face of the component's bodies."""
    center, axis = runtime.to_world(pattern.Center), runtime.to_world_dir(pattern.Axis).unit()
    for fbody in runtime.component.bRepBodies:
        for face in fbody.faces:
            if face.geometry.surfaceType != adsk.core.SurfaceTypes.CylinderSurfaceType:
                continue
            cylinder = cast(adsk.core.Cylinder, face.geometry)
            direction = vec_of(cylinder.axis)
            if abs(abs(direction.dot(axis)) - 1.0) > 1e-6:
                continue
            offset = center.sub(vec_of(cylinder.origin))
            if offset.sub(direction.scale(offset.dot(direction))).len() > 1e-5:
                continue
            axes: adsk.fusion.ConstructionAxes = runtime.component.constructionAxes
            axisInput: adsk.fusion.ConstructionAxisInput = axes.createInput()
            axisInput.setByCircularFace(face)
            entity = axes.add(axisInput)
            solids.name_feature(entity, name)
            entity.isLightBulbOn = False
            return entity
    # No face lies on the axis (a revolved blank is a cone), so a construction line along it is the axis. The line lies
    # in the base plane; axis_line refuses an axis that does not.
    return runtime.axis_line(pattern.Center, pattern.Axis, name)


@logged
def decad_pattern_copies(tooth, pattern, name):
    _settle(tooth)
    return [_placed(copy, tooth) for copy in _circular_pattern(tooth, pattern, name)]


def _circular_pattern(tooth, pattern, name):
    runtime = tooth.runtime
    axis = _axis_through(runtime, pattern, name + ' Axis')
    entities = adsk.core.ObjectCollection.create()
    entities.add(tooth.body)
    patterns: adsk.fusion.CircularPatternFeatures = runtime.component.features.circularPatternFeatures
    patternInput: adsk.fusion.CircularPatternFeatureInput = patterns.createInput(entities, axis)
    patternInput.quantity = adsk.core.ValueInput.createByReal(pattern.Count)
    patternInput.totalAngle = adsk.core.ValueInput.createByString('360 deg')
    patternInput.isSymmetric = False
    feature: adsk.fusion.CircularPatternFeature = patterns.add(patternInput)
    solids.name_feature(feature, name)
    # The result may or may not list the original body; the copies are the others.
    source = tooth.body
    copies = [Body(runtime, b) for b in feature.bodies if not b == source]
    if not copies:
        raise RuntimeError(f'{name}: the pattern made no copies')
    return copies


class Option:
    """A decad option the Fusion kernel has no use for: decad's mesh booleans take hints, Fusion's exact kernel none."""

    def __init__(self, what):
        self.what = what


def decad_with_matching_faces():
    return Option('matching faces')


def decad_with_copy_placement(turn):
    return Option(turn)


def _leave_container(body):
    if body.container is not None:
        if any(held is body for held in body.container.bodies):
            body.container.bodies.remove(body)
        body.container = None


def _combine(base, tools, operation, name):
    collection = adsk.core.ObjectCollection.create()
    for tool in tools:
        collection.add(tool.body)
    combines: adsk.fusion.CombineFeatures = base.runtime.component.features.combineFeatures
    combineInput: adsk.fusion.CombineFeatureInput = combines.createInput(base.body, collection)
    combineInput.operation = operation
    feature = combines.add(combineInput)
    solids.name_feature(feature, name)
    # The tools are consumed, so they no longer belong to a container.
    for tool in tools:
        _leave_container(tool)
    return base


def _depend(body, lazy):
    """Record that a pending union or copy takes body, so that an operation on body makes it first. [PB-LAZY-JOIN]"""
    body.__dict__.setdefault('_dependents', []).append(lazy)


def _settle(body, upto=None):
    """Make the pending copies of body and the pending unions that take it, in the order the gallery asked for them,
    before anything else changes or reads body. The lazy batching then gives every body the shape the eager sequence
    of features would. With upto, only what was asked for before upto is made; once upto is no longer pending,
    everything before it was made already. Copies asked for one after another are made together, so the copies of one
    tooth stay one pattern. [PB-LAZY-JOIN]"""
    pending = body.__dict__.get('_dependents')
    if not pending:
        return
    if upto is not None and not any(entry is upto for entry in pending):
        return
    while pending and pending[0] is not upto:
        entry = pending.pop(0)
        if isinstance(entry, CopyBody):
            run = [entry]
            while pending and pending[0] is not upto and isinstance(pending[0], CopyBody):
                run.append(pending.pop(0))
            _make_copies(run)
        elif entry._body is None and not entry._absorbed:
            entry._realize()


def _settle_all(*bodies):
    for body in bodies:
        _settle(body)


class UnionBody(Body):
    """A union the gallery asked for, not yet made. Fusion's exact kernel joins any number of bodies in one
    combine, and one combine of thirty teeth is far cheaper than thirty. So a union is recorded, a union of unions
    is flattened, and the single combine is made when something first needs the body's geometry. [PB-LAZY-JOIN]"""

    def __init__(self, runtime, base, others, name):
        self.runtime = runtime
        self.container = base.container
        self._name = name
        self._body = None
        self._absorbed = False
        self._parts = [base] + list(others)
        for part in self._parts:
            _depend(part, self)
        # The union stands where its base stood: the base is the body the container holds.
        if base.container is not None and base in base.container.bodies:
            base.container.bodies[base.container.bodies.index(base)] = self
            base.container = None

    @property
    def body(self):
        if self._absorbed:
            raise ConsumedBody(f'{self._name}: a union that a later union took over was used again')
        if self._body is None:
            self._realize()
        return self._body

    @body.setter
    def body(self, value):
        # A body that moves to a component is a new Fusion body.
        self._body = value

    def _realize(self):
        # What the gallery asked of each part before this union comes first: a copy of a tool is made before the
        # join consumes the tool, and an earlier union that takes a part is joined first.
        for part in self._parts:
            _settle(part, upto=self)
        _realize_copies(self._parts)
        base, tools = self._parts[0], self._parts[1:]
        _combine(base, tools, adsk.fusion.FeatureOperations.JoinFeatureOperation, self._name)
        self._body = base.body
        self._parts = []


@logged
def decad_union(base, *others, name):
    for body in (base,) + others:
        if isinstance(body, UnionBody) and body._absorbed:
            raise ConsumedBody(f'{name}: {body._name} was joined into a later union and cannot be joined again')
    parts = []
    for other in others:
        # A pending union of the tool joins the same base, so its parts become tools of this one.
        if isinstance(other, UnionBody) and other._body is None:
            parts.extend(other._parts)
            other._parts = []
            other._absorbed = True
            # The eager join consumes the tool, so the union it stood for leaves its container.
            _leave_container(other)
        else:
            parts.append(other)
            # The eager join consumes its tools, so they leave their containers when the union is asked for.
            _leave_container(other)
    if isinstance(base, UnionBody) and base._body is None:
        base._parts.extend(parts)
        for part in parts:
            _depend(part, base)
        base._name = name
        return base
    return UnionBody(base.runtime, base, parts, name)


@logged
def decad_cut(base, tool, *options, name):
    _settle_all(base, tool)
    return _combine(base, [tool], adsk.fusion.FeatureOperations.CutFeatureOperation, name)


@logged
def decad_intersect(base, tool, *options, name):
    _settle_all(base, tool)
    return _combine(base, [tool], adsk.fusion.FeatureOperations.IntersectFeatureOperation, name)


class CopyRotation:
    def __init__(self, center, axis, angle):
        self.center, self.axis, self.angle = center, axis, angle


def decad_with_copy_rotation(center, axis, angle):
    return CopyRotation(center, axis, angle)


class CopyBody(Body):
    """A turned copy of a body the gallery asked for, not yet made. The gallery copies a tooth once per angle, and
    Fusion makes all the copies of one body at equal angles with a single circular pattern, so the copies are made
    when something first needs one of them. [PB-LAZY-JOIN]"""

    def __init__(self, runtime, source, rotation, name):
        self.runtime = runtime
        self.container = source.container
        self.source, self.rotation, self._name = source, rotation, name
        self._body = None
        _depend(source, self)

    @property
    def body(self):
        if self._body is None:
            self._make()
        return self._body

    @body.setter
    def body(self, value):
        self._body = value

    def _make(self):
        # The copy is of the source as it stood when the copy was asked for.
        _settle(self.source, upto=self)
        runtime = self.runtime
        entities = adsk.core.ObjectCollection.create()
        entities.add(self.source.body)
        copies: adsk.fusion.CopyPasteBodies = runtime.component.features.copyPasteBodies
        feature = copies.add(entities)
        solids.name_feature(feature, self._name)
        if feature.bodies.count != 1:
            raise RuntimeError(f'{self._name}: expected one copied body, got {feature.bodies.count}')
        self._body = feature.bodies.item(0)
        if self.rotation is not None:
            turned = Body(runtime, self._body)
            decad_transform(turned, self.rotation, name=self._name + ' Turn')


def _turn_angle(rotation):
    return rotation.angle.base() if hasattr(rotation.angle, 'base') else rotation.angle


@logged
def decad_copy(body, *options, name):
    """A copy of the body, turned by the rotation option when there is one."""
    rotation = None
    for option in options:
        if isinstance(option, CopyRotation):
            rotation = Rotation(option.axis, _turn_angle(option), option.center)
    copy = CopyBody(body.runtime, body, rotation, name)
    if body.container is not None:
        body.container.bodies.append(copy)
    return copy


def _make_copies(copies):
    """Make pending copies, the ones at equal angles about one axis as one pattern and the others one by one."""
    _realize_copies(copies)
    for copy in copies:
        if copy._body is None:
            copy._make()


def _realize_copies(parts):
    """Make the pending copies among parts. The copies of one body at the angles 2 pi k / n for k = 1 to n - 1 about
    one axis are one circular pattern; any other copy is made on its own when its body is first read."""
    groups = {}
    for part in parts:
        if isinstance(part, CopyBody) and part._body is None and part.rotation is not None:
            groups.setdefault(id(part.source), []).append(part)
    for copies in groups.values():
        count = len(copies) + 1
        if count < 3:
            continue
        first = copies[0].rotation
        axis = first.axis.unit()
        center = first.center if first.center is not None else Vec(0.0, 0.0, 0.0)
        step = 2 * math.pi / count
        wanted = sorted(_turn_angle(c.rotation) % (2 * math.pi) for c in copies)
        same = all(c.rotation.axis.unit().sub(axis).len() < 1e-9 and _same_centre(c.rotation.center, first.center)
                   for c in copies)
        if not same or any(abs(a - step * (k + 1)) > 1e-9 for k, a in enumerate(wanted)):
            continue
        _pattern_copies(copies, axis, center, count, step)


def _same_centre(a, b):
    if a is None or b is None:
        return a is b
    return a.sub(b).len() < 1e-9


def _pattern_copies(copies, axis, center, count, step):
    """One circular pattern of the source for all its pending copies. Each new body is given to the copy whose angle
    about the rotation centre and axis matches the body's centroid, since Fusion does not say which instance is
    which."""
    source, runtime = copies[0].source, copies[0].runtime
    name = copies[0]._name
    made = _circular_pattern(source, CircularPattern(center, axis, count), name)
    if len(made) != len(copies):
        raise FusionRefused(f'{name}: the pattern made {len(made)} copies; want {len(copies)} [PB-EMPTY-RESULT]')
    perpendicular = Vec(0.0, 0.0, 1.0) if abs(axis.z) < 0.9 else Vec(1.0, 0.0, 0.0)
    e1 = axis.cross(perpendicular).unit()
    e2 = axis.cross(e1)

    def angle(body):
        # The raw centre of mass: reading the source through Body would make its pending copies, which are these.
        c = Centroid(runtime, body.body.physicalProperties.centerOfMass).Value.sub(center)
        return math.atan2(c.dot(e2), c.dot(e1))

    origin = angle(source)
    pool = list(made)
    for copy in sorted(copies, key=lambda c: _turn_angle(c.rotation)):
        wanted = _turn_angle(copy.rotation)
        best = min(pool, key=lambda b: abs(math.remainder(angle(b) - origin - wanted, 2 * math.pi)))
        if abs(math.remainder(angle(best) - origin - wanted, 2 * math.pi)) > step / 4:
            raise RuntimeError(f'{name}: no pattern instance lies at {wanted:.6f} rad')
        pool.remove(best)
        copy._body = best.body


@logged
def decad_remove(body, name):
    """Delete a body from the design. The body stays readable to the gallery but nothing takes it again."""
    _settle(body)
    removes: adsk.fusion.RemoveFeatures = body.runtime.component.features.removeFeatures
    feature = removes.add(body.body)
    solids.name_feature(feature, name)
    if body.container is not None:
        body.container.bodies.remove(body)
        body.container = None


def _planar_face_through(body, world):
    """A planar face of the body that contains the point."""
    for face in body.body.faces:
        if face.geometry.surfaceType != adsk.core.SurfaceTypes.PlaneSurfaceType:
            continue
        plane = cast(adsk.core.Plane, face.geometry)
        offset = vec_of(plane.origin).sub(world)
        if abs(offset.dot(vec_of(plane.normal).unit())) <= 1e-5:
            return face
    raise RuntimeError(f'{body.body.name}: no planar face passes through the scale anchor')


@logged
def decad_scaled_at(body, anchor, factor, name):
    """Scale the body uniformly about a point of the build frame, in place."""
    _settle(body)
    runtime = body.runtime
    world = runtime.to_world(anchor)
    where = adsk.core.Point3D.create(world.x, world.y, world.z)
    face = _planar_face_through(body, world)
    # A construction point at a bare Point3D is valid only in direct modeling, so the base point is a sketch point
    # on a face that passes through the anchor. [PB-SCALE-BASE-POINT]
    anchorSketch = runtime.component.sketches.add(face)
    solids.name_feature(anchorSketch, name + ' Anchor')
    base = anchorSketch.sketchPoints.add(anchorSketch.modelToSketchSpace(where))
    anchorSketch.isLightBulbOn = False
    entities = adsk.core.ObjectCollection.create()
    entities.add(body.body)
    scales: adsk.fusion.ScaleFeatures = runtime.component.features.scaleFeatures
    scaleInput: adsk.fusion.ScaleFeatureInput = scales.createInput(
        entities, base, adsk.core.ValueInput.createByReal(factor))
    feature = scales.add(scaleInput)
    solids.name_feature(feature, name)
    return body


@logged
def decad_split(target, sheet, name):
    """Cut a solid with a surface body and return its two pieces, the one nearer the local origin first. The gallery
    walks the slices from the heel toward the apex, so the first piece is the one the next plane can still meet."""
    _settle_all(target, sheet)
    runtime = target.runtime
    splits: adsk.fusion.SplitBodyFeatures = runtime.component.features.splitBodyFeatures
    splitInput: adsk.fusion.SplitBodyFeatureInput = splits.createInput(target.body, sheet.body, True)
    feature = splits.add(splitInput)
    solids.name_feature(feature, name)
    if feature.bodies.count != 2:
        raise RuntimeError(f'{name}: the sheet made {feature.bodies.count} pieces; want two')
    container = target.container
    pieces = []
    for fbody in feature.bodies:
        pieces.append(Body(runtime, fbody))
    pieces.sort(key=lambda piece: piece.centroid().Value.len())
    # Fusion keeps the splitting tool as a body of its own, where decad consumes it, so the sheet is removed. Left in
    # place it shows as a large plate across the gear. [PB-SPLIT-TOOL]
    decad_remove(sheet, name + ' Sheet Removal')
    # The target is consumed; the pieces take its place.
    for gone in (target,):
        if gone.container is not None:
            gone.container.bodies.remove(gone)
            gone.container = None
    if container is not None:
        for piece in pieces:
            container.bodies.append(piece)
            piece.container = container
    return pieces


@logged
def decad_loft_faces(doc, *faces, name, body):
    owners = [face.owner for face in faces if face.owner is not None]
    _settle_all(*owners)
    lofts: adsk.fusion.LoftFeatures = doc.component.features.loftFeatures
    loftInput: adsk.fusion.LoftFeatureInput = lofts.createInput(adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    for face in faces:
        loftInput.loftSections.add(face.face)
    loft: adsk.fusion.LoftFeature = lofts.add(loftInput)
    solids.name_feature(loft, name)
    if loft.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {loft.bodies.count}')
    fbody: adsk.fusion.BRepBody = loft.bodies.item(0)
    solids.name_feature(fbody, body)
    # The loft belongs where the body of its first section is.
    return _placed(Body(doc, fbody), owners[0] if owners else None)


@logged
def decad_fillet(body, selector, radius, name):
    _settle(body)
    with timed(f'{name} edge selection'):
        edges = _edge_collection(selector, body, name)
    fillets: adsk.fusion.FilletFeatures = body.runtime.component.features.filletFeatures
    filletInput: adsk.fusion.FilletFeatureInput = fillets.createInput()
    filletInput.addConstantRadiusEdgeSet(edges, value_input(radius, body.runtime.scale), False)
    with timed(f'{name} feature'):
        feature = fillets.add(filletInput)
    solids.name_feature(feature, name)
    return body


@logged
def decad_chamfer(body, selector, setback, name):
    _settle(body)
    with timed(f'{name} edge selection'):
        edges = _edge_collection(selector, body, name)
    chamfers: adsk.fusion.ChamferFeatures = body.runtime.component.features.chamferFeatures
    chamferInput: adsk.fusion.ChamferFeatureInput = chamfers.createInput2()
    chamferInput.chamferEdgeSets.addEqualDistanceChamferEdgeSet(edges, value_input(setback, body.runtime.scale), False)
    with timed(f'{name} feature'):
        feature = chamfers.add(chamferInput)
    solids.name_feature(feature, name)
    return body


@logged
def decad_loft(doc, lowerSketch, lowerProfile, upperSketch, upperProfile, name, body):
    if doc.sketch_only:
        raise SketchOnly()
    lofts: adsk.fusion.LoftFeatures = doc.component.features.loftFeatures
    loftInput: adsk.fusion.LoftFeatureInput = lofts.createInput(adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    loftInput.loftSections.add(lowerProfile.fprofile)
    loftInput.loftSections.add(upperProfile.fprofile)
    loft: adsk.fusion.LoftFeature = lofts.add(loftInput)
    solids.name_feature(loft, name)
    if loft.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {loft.bodies.count}')
    fbody: adsk.fusion.BRepBody = loft.bodies.item(0)
    solids.name_feature(fbody, body)
    return _placed(Body(doc, fbody), lowerSketch)


class Rotation:
    """A turn about an axis, by an angle in radians. The axis passes through the local origin unless a centre is given."""

    def __init__(self, axis, angle, center=None):
        self.axis, self.angle, self.center = axis, angle, center


def r3_rotation(axis, angle):
    return Rotation(axis, angle)


def r3_rotation_around(center, axis, angle):
    return Rotation(axis, angle, center)


def units_scalar(x):
    return x


def placement_place(body, frame):
    """The gallery moves a finished gear to its Placement. Here the build already lies on the Target Plane at the
    Anchor Point, so there is no placement to apply."""
    if frame is not None:
        raise RuntimeError('a placement frame is not translated: the add-in builds on the Target Plane')
    return body


@logged
def decad_transform(body, transform, name):
    _settle(body)
    runtime = body.runtime
    if not isinstance(transform, Rotation):
        raise RuntimeError(f'{name}: only a rotation is translated')
    if transform.angle == 0:
        # A zero turn is no move, and Fusion refuses a move by the identity with "invalid transform".
        return body
    axis = runtime.to_world_dir(transform.axis).unit()
    origin = runtime.placement.origin() if transform.center is None else runtime.to_world(transform.center)
    matrix = adsk.core.Matrix3D.create()
    matrix.setToRotation(transform.angle, adsk.core.Vector3D.create(axis.x, axis.y, axis.z),
                         adsk.core.Point3D.create(origin.x, origin.y, origin.z))
    entities = adsk.core.ObjectCollection.create()
    entities.add(body.body)
    moves: adsk.fusion.MoveFeatures = runtime.component.features.moveFeatures
    moveInput: adsk.fusion.MoveFeatureInput = moves.createInput2(entities)
    moveInput.defineAsFreeMove(matrix)
    feature = moves.add(moveInput)
    solids.name_feature(feature, name)
    return body


class FullRevolution:
    pass


def decad_full_revolution():
    return FullRevolution()


class Point2:
    def __init__(self, U, V):
        self.U, self.V = U, V


def decad_point2(U, V):
    return Point2(U, V)


class SketchLine:
    def __init__(self, Start, End):
        self.Start, self.End = Start, End


def decad_sketch_line(Start, End):
    return SketchLine(Start, End)


@logged
def decad_revolve(doc, sketch, profile, axis, extent, name):
    if not isinstance(extent, FullRevolution):
        raise RuntimeError(f'{name}: only a full revolution is translated')
    line = sketch.find_axis_line(axis)
    if line is None:
        if abs(axis.Start.U) > 1e-12 or abs(axis.Start.V) > 1e-12:
            raise RuntimeError(f'{name}: only an axis from the local origin is translated')
        line = doc.axis_line(Vec(0, 0, 0), Vec(axis.End.U - axis.Start.U, axis.End.V - axis.Start.V, 0), 'Shaft Axis')
    revolves: adsk.fusion.RevolveFeatures = doc.component.features.revolveFeatures
    revolveInput: adsk.fusion.RevolveFeatureInput = revolves.createInput(
        profile.fprofile, line, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    revolveInput.setAngleExtent(False, adsk.core.ValueInput.createByString('360 deg'))
    feature: adsk.fusion.RevolveFeature = revolves.add(revolveInput)
    solids.name_feature(feature, name)
    if feature.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {feature.bodies.count}')
    return _placed(Body(doc, feature.bodies.item(0)), sketch)


@logged
def decad_loft_from_point(doc, point, sketch, profile, name, body):
    """Loft from a point to a profile. The gallery's point is the common apex, the local origin, which is the anchor."""
    if abs(point.x) > 1e-9 or abs(point.y) > 1e-9 or abs(point.z) > 1e-9:
        raise RuntimeError(f'{name}: only a loft from the local origin is translated')
    lofts: adsk.fusion.LoftFeatures = doc.component.features.loftFeatures
    loftInput: adsk.fusion.LoftFeatureInput = lofts.createInput(adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    loftInput.loftSections.add(doc.anchor)
    loftInput.loftSections.add(profile.fprofile)
    loft: adsk.fusion.LoftFeature = lofts.add(loftInput)
    solids.name_feature(loft, name)
    if loft.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {loft.bodies.count}')
    fbody: adsk.fusion.BRepBody = loft.bodies.item(0)
    solids.name_feature(fbody, body)
    return _placed(Body(doc, fbody), sketch)


def select_embedded_tooth_profile(profiles, root):
    """The region of a tooth sketch whose root circle cuts across the flanks: valid, with no hole, bounded by four
    curves of which two are the flank splines trimmed at the root circle. Fusion's regions carry their trimmed
    curves, so the region is found by that shape. [PB-EMBEDDED-TOOTH]"""
    found = []
    for profile in profiles:
        if not profile.Valid or profile.Holes or len(profile.Outer) != 4:
            continue
        splines = [c for c in profile.Outer if c.geometry.curveType == adsk.core.Curve3DTypes.NurbsCurve3DCurveType]
        if len(splines) == 2:
            found.append(profile)
    if len(found) != 1:
        raise RuntimeError(f'found {len(found)} embedded virtual tooth regions among {len(profiles)} regions; want one')
    return found[0]


class MirrorFrame:
    def __init__(self, Frame):
        self.Frame = Frame


def decad_mirror_frame(Frame):
    return MirrorFrame(Frame)


def _mirror_plane_frame(runtime, frame):
    """A mirror needs only the plane, not the frame's axes or where in the plane its origin lies. A plane parallel to
    the base plane is given as the build frame moved along its normal, the one parallel frame create_plane_from_frame
    translates."""
    base = runtime.frame
    if abs(abs(frame.n().dot(base.n())) - 1.0) > 1e-9:
        return frame
    height = frame.origin().sub(base.origin()).dot(base.n())
    return Frame(base.origin().add(base.n().scale(height)), base.u(), base.v(), base.n())


@logged
def decad_mirrored_copy(source, mirror, name, body):
    _settle(source)
    runtime = source.runtime
    plane = runtime.create_plane_from_frame(_mirror_plane_frame(runtime, mirror.Frame), name + ' Plane')
    entities = adsk.core.ObjectCollection.create()
    entities.add(source.body)
    mirrors: adsk.fusion.MirrorFeatures = runtime.component.features.mirrorFeatures
    mirrorInput: adsk.fusion.MirrorFeatureInput = mirrors.createInput(entities, plane.entity)
    mirrorInput.isCombine = False
    feature: adsk.fusion.MirrorFeature = mirrors.add(mirrorInput)
    solids.name_feature(feature, name)
    original = source.body
    copies = [b for b in feature.bodies if not b == original]
    if len(copies) != 1:
        raise RuntimeError(f'{name}: expected one mirrored body, got {len(copies)}')
    solids.name_feature(copies[0], body)
    return _placed(Body(runtime, copies[0]), source)
